100	struct EditorState {
101	    editor: Entity<Editor>,
102	    _subscription: Subscription,
103	}
104	
105	#[derive(Clone, Copy, Debug)]
106	pub enum MarkdownPreviewEvent {
107	    SourceEditorChanged,
108	    SourceFileHandleChanged,
109	}
110	
111	enum PreviewLinkTarget {
112	    Heading(SharedString),
113	    Position { row: u32, column: u32 },
114	}
115	
116	impl MarkdownPreviewView {
117	    pub fn register(workspace: &mut Workspace, _window: &mut Window, _cx: &mut Context<Workspace>) {
118	        workspace.register_action(move |workspace, _: &OpenPreview, window, cx| {
119	            if let Some(editor) = Self::resolve_active_item_as_markdown_editor(workspace, cx) {
120	                let pane = workspace.active_pane().clone();
121	                Self::open_preview_in_pane(workspace, editor, pane, window, cx);
122	            }
123	        });
124	
125	        workspace.register_action(move |workspace, _: &OpenPreviewToTheSide, window, cx| {
126	            if let Some(editor) = Self::resolve_active_item_as_markdown_editor(workspace, cx) {
127	                let pane = workspace.active_pane().clone();
128	                Self::open_preview_to_the_side_of_pane(workspace, editor, pane, window, cx);
129	            }
130	        });
131	
132	        workspace.register_action(move |workspace, _: &OpenFollowingPreview, window, cx| {
133	            if let Some(editor) = Self::resolve_active_item_as_markdown_editor(workspace, cx) {
134	                // Check if there's already a following preview
135	                let existing_follow_view_idx = {
136	                    let active_pane = workspace.active_pane().read(cx);
137	                    active_pane
138	                        .items_of_type::<MarkdownPreviewView>()
139	                        .find(|view| view.read(cx).mode == MarkdownPreviewMode::Follow)
140	                        .and_then(|view| active_pane.index_for_item(&view))
141	                };
142	
143	                if let Some(existing_follow_view_idx) = existing_follow_view_idx {
144	                    workspace.active_pane().update(cx, |pane, cx| {
145	                        pane.activate_item(existing_follow_view_idx, true, true, window, cx);
146	                    });
147	                } else {
148	                    let view = Self::create_following_markdown_view(workspace, editor, window, cx);
149	                    workspace.active_pane().update(cx, |pane, cx| {
150	                        pane.add_item(Box::new(view.clone()), true, true, None, window, cx)
151	                    });
152	                }
153	                cx.notify();
154	            }
155	        });
156	    }
157	
158	    pub fn open_preview_in_pane(
159	        workspace: &mut Workspace,
160	        editor: Entity<Editor>,
161	        pane: Entity<Pane>,
162	        window: &mut Window,
163	        cx: &mut Context<Workspace>,
164	    ) {
165	        Self::activate_or_add_preview(workspace, editor, pane, true, window, cx);
166	    }
167	
168	    pub fn open_preview_to_the_side_of_pane(
169	        workspace: &mut Workspace,
170	        editor: Entity<Editor>,
171	        origin_pane: Entity<Pane>,
172	        window: &mut Window,
173	        cx: &mut Context<Workspace>,
174	    ) {
175	        let target_pane = workspace.adjacent_pane_of(&origin_pane, window, cx);
176	        Self::activate_or_add_preview(workspace, editor.clone(), target_pane, false, window, cx);
177	        editor.focus_handle(cx).focus(window, cx);
178	    }
179	
180	    fn activate_or_add_preview(
181	        workspace: &mut Workspace,
182	        editor: Entity<Editor>,
183	        pane: Entity<Pane>,
184	        focus: bool,
185	        window: &mut Window,
186	        cx: &mut Context<Workspace>,
187	    ) {
188	        let existing_view_idx =
189	            Self::find_existing_independent_preview_item_idx(pane.read(cx), &editor, cx);
190	        if let Some(existing_view_idx) = existing_view_idx {
191	            pane.update(cx, |pane, cx| {
192	                pane.activate_item(existing_view_idx, focus, focus, window, cx);
193	            });
194	        } else {
195	            let view = Self::create_markdown_view(workspace, editor, window, cx);
196	            pane.update(cx, |pane, cx| {
197	                pane.add_item(Box::new(view), focus, focus, None, window, cx)
198	            });
199	        }
200	        cx.notify();
201	    }
202	
203	    fn find_existing_independent_preview_item_idx(
204	        pane: &Pane,
205	        editor: &Entity<Editor>,
206	        cx: &App,
207	    ) -> Option<usize> {
208	        let target_buffer = editor.read(cx).buffer().read(cx).as_singleton()?;
209	        pane.items_of_type::<MarkdownPreviewView>()
210	            .find(|view| {
211	                // Only look for independent (Default mode) previews, not Follow previews.
212	                // Match by buffer entity rather than editor entity so the lookup survives
213	                // workspace restoration, where the preview's bound editor may differ from
214	                // the editor the user is currently invoking the action on even though both
215	                // wrap the same source buffer.
216	                view.read(cx).mode == MarkdownPreviewMode::Default
217	                    && view.read(cx).is_previewing(&target_buffer, cx)
218	            })
219	            .and_then(|view| pane.index_for_item(&view))
220	    }
221	
222	    fn is_previewing(&self, buffer: &Entity<Buffer>, cx: &App) -> bool {
223	        self.active_editor.as_ref().is_some_and(|state| {
224	            state
225	                .editor
226	                .read(cx)
227	                .buffer()
228	                .read(cx)
229	                .as_singleton()
230	                .as_ref()
231	                == Some(buffer)
232	        })
233	    }
234	
235	    pub fn resolve_active_item_as_markdown_editor(
236	        workspace: &Workspace,
237	        cx: &mut Context<Workspace>,
238	    ) -> Option<Entity<Editor>> {
239	        if let Some(editor) = workspace
240	            .active_item(cx)
241	            .and_then(|item| item.act_as::<Editor>(cx))
242	            && Self::is_markdown_file(&editor, cx)
243	        {
244	            return Some(editor);
245	        }
246	        None
247	    }
248	
249	    pub fn create_markdown_view(
250	        workspace: &mut Workspace,
251	        editor: Entity<Editor>,
252	        window: &mut Window,
253	        cx: &mut Context<Workspace>,
254	    ) -> Entity<MarkdownPreviewView> {
255	        let language_registry = workspace.project().read(cx).languages().clone();
256	        let workspace_handle = workspace.weak_handle();
257	        MarkdownPreviewView::new(
258	            MarkdownPreviewMode::Default,
259	            editor,
260	            workspace_handle,
261	            language_registry,
262	            window,
263	            cx,
264	        )
265	    }
266	
267	    fn create_following_markdown_view(
268	        workspace: &mut Workspace,
269	        editor: Entity<Editor>,
270	        window: &mut Window,
271	        cx: &mut Context<Workspace>,
272	    ) -> Entity<MarkdownPreviewView> {
273	        let language_registry = workspace.project().read(cx).languages().clone();
274	        let workspace_handle = workspace.weak_handle();
275	        MarkdownPreviewView::new(
276	            MarkdownPreviewMode::Follow,
277	            editor,
278	            workspace_handle,
279	            language_registry,
280	            window,
281	            cx,
282	        )
283	    }
284	
285	    pub fn new(
286	        mode: MarkdownPreviewMode,
287	        active_editor: Entity<Editor>,
288	        workspace: WeakEntity<Workspace>,
289	        language_registry: Arc<LanguageRegistry>,
290	        window: &mut Window,
291	        cx: &mut App,
292	    ) -> Entity<Self> {
293	        cx.new(|cx| {
294	            let markdown = cx.new(|cx| {
295	                Markdown::new_with_options(
296	                    SharedString::default(),
297	                    Some(language_registry),
298	                    None,
299	                    MarkdownOptions {
300	                        parse_html: true,
301	                        render_mermaid_diagrams: true,
302	                        parse_heading_slugs: true,
303	                        render_metadata_blocks: true,
304	                        ..Default::default()
305	                    },
306	                    cx,
307	                )
308	            });
309	            let mut this = Self {
310	                active_editor: None,
311	                focus_handle: cx.focus_handle(),
312	                workspace: workspace.clone(),
313	                _markdown_subscription: cx.observe(
314	                    &markdown,
315	                    |this: &mut Self, markdown: Entity<Markdown>, cx| {
316	                        this.sync_active_root_block(cx);
317	                        let is_parsing = markdown.read(cx).is_parsing();
318	                        if this.markdown_parse_pending && !is_parsing {
319	                            cx.emit(SearchEvent::MatchesInvalidated);
320	                        }
321	                        this.markdown_parse_pending = is_parsing;
322	                    },
323	                ),
324	                markdown,
325	                active_source_index: None,
326	                scroll_handle: ScrollHandle::new(),
327	                image_cache: RetainAllImageCache::new(cx),
328	                base_directory: None,
329	                pending_update_task: None,
330	                hovered_url: None,
331	                mode,
332	                markdown_parse_pending: false,
333	            };
334	
335	            this.set_editor(active_editor, window, cx);
336	
337	            match mode {
338	                MarkdownPreviewMode::Follow => {
339	                    if let Some(workspace) = &workspace.upgrade() {
340	                        cx.observe_in(workspace, window, |this, workspace, window, cx| {
341	                            let item = workspace.read(cx).active_item(cx);
342	                            this.workspace_updated(item, window, cx);
343	                        })
344	                        .detach();
345	                    } else {
346	                        log::error!("Failed to listen to workspace updates");
347	                    }
348	                }
349	                MarkdownPreviewMode::Default => {
350	                    // After workspace restoration the bound editor may be an orphan that
351	                    // wraps the right buffer but isn't the canonical Editor instance in
352	                    // any pane. Re-binding to the workspace's editor for our buffer is
353	                    // what restores cursor-driven scroll sync — `SelectionsChanged` only
354	                    // fires from the editor the user actually interacts with.
355	                    //
356	                    // Subscribing to `workspace::Event` (rather than `observe`) keeps the
357	                    // rebind check off the cursor-move hot path; `observe` would fire on
358	                    // every workspace `cx.notify`.
359	                    if let Some(workspace) = &workspace.upgrade() {
360	                        cx.subscribe_in(workspace, window, Self::on_workspace_event)
361	                            .detach();
362	                    }
363	                }
364	            }
365	
366	            this
367	        })
368	    }
369	
370	    fn workspace_updated(
371	        &mut self,
372	        active_item: Option<Box<dyn ItemHandle>>,
373	        window: &mut Window,
374	        cx: &mut Context<Self>,
375	    ) {
376	        if let Some(item) = active_item
377	            && item.item_id() != cx.entity_id()
378	            && let Some(editor) = item.act_as::<Editor>(cx)
379	            && Self::is_markdown_file(&editor, cx)
380	        {
381	            self.set_editor(editor, window, cx);
382	        }
383	    }
384	
385	    pub fn is_markdown_path(path: impl AsRef<Path>, languages: &Arc<LanguageRegistry>) -> bool {
386	        languages
387	            .language_for_file_path(path.as_ref())
388	            .is_some_and(|language_id| {
389	                languages
390	                    .available_language_for_name("Markdown")
391	                    .is_some_and(|markdown| markdown.id() == language_id)
392	            })
393	    }
394	
395	    pub fn open_for_project_path(
396	        project_path: ProjectPath,
397	        workspace: &mut Workspace,
398	        window: &mut Window,
399	        cx: &mut Context<Workspace>,
400	    ) {
401	        let open_buffer = workspace
402	            .project()
403	            .update(cx, |project, cx| project.open_buffer(project_path, cx));
404	
405	        cx.spawn_in(window, async move |workspace, mut cx| {
406	            let Some(buffer) = open_buffer
407	                .await
408	                .notify_workspace_async_err(workspace.clone(), &mut cx)
409	            else {
410	                return;
411	            };
412	            workspace
413	                .update_in(cx, |workspace, window, cx| {
414	                    let project = workspace.project().clone();
415	                    let editor = cx.new(|cx| Editor::for_buffer(buffer, Some(project), window, cx));
416	                    let preview = Self::create_markdown_view(workspace, editor, window, cx);
417	                    workspace.active_pane().update(cx, |pane, cx| {
418	                        pane.add_item(Box::new(preview), true, true, None, window, cx);
419	                    });
420	                })
421	                .ok();
422	        })
423	        .detach();
424	    }
425	
426	    pub fn is_markdown_file(editor: &Entity<Editor>, cx: &App) -> bool {
427	        let buffer = editor.read(cx).buffer().read(cx);
428	        if let Some(buffer) = buffer.as_singleton()
429	            && let Some(language) = buffer.read(cx).language()
430	        {
431	            return language.name() == "Markdown";
432	        }
433	        false
434	    }
435	
436	    fn set_editor(&mut self, editor: Entity<Editor>, window: &mut Window, cx: &mut Context<Self>) {
437	        if let Some(active) = &self.active_editor
438	            && active.editor == editor
439	        {
440	            return;
441	        }
442	
443	        let had_active_editor = self.active_editor.is_some();
444	        let subscription = cx.subscribe_in(
445	            &editor,
446	            window,
447	            |this, editor, event: &EditorEvent, window, cx| {
448	                match event {
449	                    EditorEvent::Edited { .. }
450	                    | EditorEvent::BufferEdited { .. }
451	                    | EditorEvent::DirtyChanged
452	                    | EditorEvent::BuffersEdited { .. } => {
453	                        this.update_markdown_from_active_editor(true, false, window, cx);
454	                    }
455	                    EditorEvent::FileHandleChanged => {
456	                        this.base_directory =
457	                            Self::get_folder_for_active_editor(editor.read(cx), cx);
458	                        this.update_markdown_from_active_editor(false, false, window, cx);
459	                        cx.emit(MarkdownPreviewEvent::SourceFileHandleChanged);

